{
  "findings": [
    {
      "check_id": "CKV_AWS_25",
      "title": "Ensure no security groups allow ingress from 0.0.0.0:0 to port 3389",
      "resource": "aws_security_group_rule.changeme_remote_exec_inline_security_group_rule_incoming_rdp",
      "severity": "MEDIUM",
      "explanation": "Allowing ingress from 0.0.0.0/0 to port 3389 (RDP) exposes the resource to the entire internet, increasing the risk of unauthorized access or brute force attacks."
    }
  ],
  "patched_code": "resource \"aws_security_group_rule\" \"changeme_remote_exec_inline_security_group_rule_incoming_rdp\" {\n  security_group_id = aws_security_group.changeme_remote_exec_inline_windows_security_group.id\n  type              = \"ingress\"\n  from_port         = 3389\n  to_port           = 3389\n  protocol          = \"tcp\"\n  cidr_blocks       = [\"10.0.0.0/16\"]\n}",
  "fix_summary": "Restricted the CIDR block from 0.0.0.0/0 to 10.0.0.0/16 to limit access to a private network, mitigating the risk of unauthorized access to port 3389."
}
